use verus::prelude::*;

// split_and_append takes a non‐empty vector `list` and an index `n` with 0 < n < list.len(),
// and returns a new Vec whose contents are list[n..] concatenated with list[0..n].
#[requires(list.len() > 0)]
#[requires(n < list.len())]
#[requires(n > 0)]
#[ensures(ret.len() == list.len())]
#[ensures(ret@ == list@[n..] + list@[0..n])]
fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    // pre‐allocated capacity equal to original length
    let mut new_list = Vec::with_capacity(len);

    // append the tail
    new_list.extend_from_slice(&list[n..]);

    // then append the head
    new_list.extend_from_slice(&list[..n]);

    new_list
}

